mapper.select:
select DISTINCT(o.ID), o.TITLE, o.TYPE, o.PID, o.PIDS, o.SORT, o.STATUS from sys_org o left join sys_role_org ro on o.id = ro.org_id left join sys_user_role ur on ro.role_id = ur.role_id left join sys_user u on u.id = ur.user_id where o.status = 1
and u.id = #{userId}
and REGEXP_LIKE(o.title, #{title})
and o.pid = #{pid}
and o.pid != #{notId}
order by o.type, o.sort

select id, name || '(' || asset_image || ')' as title, org_id as pid, asset_mode as type from asset where org_id in (select o.ID from sys_org o left join sys_role_org ro on o.id = ro.org_id left join sys_user_role ur on ro.role_id = ur.role_id left join sys_user u on u.id = ur.user_id where u.id = #{userId} and o.status = 1 ) and asset.asset_mode in (201, 42) and asset.is_del = 1
and asset.WATCH = #{watch}
order by ASSET_IMAGE asc

select id, name || '(' || asset_image || ')' as title, org_id as pid, asset_mode as type from asset where org_id in (select o.ID from sys_org o where o.status = 1) and asset.asset_mode in (201, 42) and asset.is_del = 1
and asset.WATCH = #{watch}
order by ASSET_IMAGE asc
